import {createServer,type IncomingMessage,type ServerResponse} from 'node:http';
import {readFile} from 'node:fs/promises';
import {z} from 'zod';
import {Store} from './store.js';
import {draftInput,workId,LabError} from './schemas.js';

const assets=new Map([['/','index.html'],['/app.js','app.js'],['/app.css','app.css']]);
const mime=new Map([['index.html','text/html'],['app.js','text/javascript'],['app.css','text/css']]);
function json(response:ServerResponse,status:number,value:unknown){response.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store'});response.end(JSON.stringify(value));}
async function input(request:IncomingMessage){const chunks:Buffer[]=[];for await(const chunk of request)chunks.push(Buffer.from(chunk));try{return JSON.parse(Buffer.concat(chunks).toString('utf8'));}catch{throw new LabError('INVALID_JSON','请求正文不是有效 JSON。');}}

// HTTP、CLI 与 MCP 使用同一个 Store，页面只保存尚未提交的编辑缓冲。
export function prototypeServer(store:Store,defaultWorkId:string){
  return createServer(async(request,response)=>{
    try{
      const url=new URL(request.url??'/', 'http://127.0.0.1');
      if(request.method==='GET'&&url.pathname==='/api/config'){json(response,200,{workId:defaultWorkId});return;}
      if(request.method==='GET'&&url.pathname==='/api/work'){
        const id=workId.parse(url.searchParams.get('work'));const work=store.getWork(id);
        const summary=store.exportWork(id);const chapters=store.listChapters(id).map(c=>({...store.getChapter(id,c.number)!,basisCurrent:summary.chapters.find(s=>s.number===c.number)!.basisCurrent}));
        json(response,200,{work,chapters});return;
      }
      if(request.method==='POST'&&url.pathname==='/api/draft'){
        const submitted=draftInput.parse(await input(request));const saved=store.saveDraft(submitted,'human');json(response,200,saved);return;
      }
      const asset=assets.get(url.pathname);
      if(request.method==='GET'&&asset){const bytes=await readFile(new URL('../prototype/'+asset,import.meta.url));response.writeHead(200,{'content-type':mime.get(asset)+'; charset=utf-8','cache-control':'no-store'});response.end(bytes);return;}
      json(response,404,{error:{code:'NOT_FOUND',message:'没有这个入口。'}});
    }catch(error){
      if(error instanceof z.ZodError){json(response,400,{error:{code:'INVALID_INPUT',message:'请填写完整标题、正文和有效的保存依据。'}});return;}
      if(error instanceof LabError){const status=error.code.endsWith('NOT_FOUND')?404:error.code.startsWith('STALE_')?409:400;json(response,status,{error:{code:error.code,message:error.message}});return;}
      console.error(error);json(response,500,{error:{code:'INTERNAL_ERROR',message:'本次请求未确认。请先重新读取当前稿，核对后继续。'}});
    }
  });
}

import {z} from 'zod';

export const workId=z.string().trim().regex(/^[a-z0-9-]+$/);
export const chapterNumber=z.number().int().positive();
export const workInput=z.object({
  id:workId,
  title:z.string().trim().min(1),
  purpose:z.string().trim().min(1),
  requirements:z.array(z.string().trim().min(1)).min(1),
  facts:z.array(z.string().trim().min(1)).min(1),
  outline:z.array(z.object({number:chapterNumber,titleHint:z.string().min(1),goal:z.string().min(1)})).min(1),
});
export const draftInput=z.object({
  workId,
  chapterNumber,
  expectedWorkRevision:z.number().int().positive(),
  expectedChapterRevision:z.number().int().nonnegative(),
  expectedPreviousRevisions:z.array(z.object({number:chapterNumber,revision:z.number().int().positive()})),
  title:z.string().trim().min(1),
  body:z.string().refine(value=>value.trim().length>0,'正文不能为空。'),
});
export const approvedExcerpt=z.strictObject({
  workId,
  chapterNumber,
  expectedWorkRevision:z.number().int().positive(),
  expectedChapterRevision:z.number().int().positive(),
  expectedPreviousRevisions:draftInput.shape.expectedPreviousRevisions,
  start:z.number().int().nonnegative(),
  end:z.number().int().positive(),
  originalText:z.string().min(1),
}).refine(input=>input.end>input.start,'选区结束位置必须在开始位置之后。');
export const workOutput=workInput.extend({revision:z.number().int().positive()});
export const chapterOutput=z.object({
  workId,
  number:chapterNumber,
  revision:z.number().int().positive(),
  title:z.string(),
  body:z.string(),
  status:z.enum(['draft','adopted']),
  workRevision:z.number().int().positive(),
  origin:z.enum(['human','agent']),
  taskId:z.string().nullable(),
  threadId:z.string().nullable(),
  updatedAt:z.string(),
  previousRevisions:z.array(z.object({number:chapterNumber,revision:z.number().int().positive()})).optional(),
  reviewNote:z.string().nullable().optional(),
});
export type WorkInput=z.infer<typeof workInput>;
export type DraftInput=z.infer<typeof draftInput>;
export type ApprovedExcerpt=z.infer<typeof approvedExcerpt>;

export class LabError extends Error {
  constructor(public readonly code:string,message:string){super(message);this.name='LabError';}
}

import {readFileSync,writeFileSync,mkdirSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createHash,randomUUID} from 'node:crypto';
import {parseArgs} from 'node:util';
import {Store} from '../dist/store.js';

export const tables=['works','work_versions','chapters','chapter_versions','tasks'];
export function snapshot(store){
  return Object.fromEntries(tables.map(name=>[name,store.db.prepare(`SELECT * FROM ${name} ORDER BY 1,2`).all().map(row=>({...row}))]));
}
export function seed(store){
  const bytes=readFileSync(new URL('../inputs/完整教师初始化.json',import.meta.url)),input=JSON.parse(bytes);
  const work=store.init(input.work),chapters=[];
  for(const chapter of input.chapters)chapters.push(store.saveDraft({workId:work.id,chapterNumber:chapter.number,expectedWorkRevision:work.revision,expectedChapterRevision:0,expectedPreviousRevisions:chapters.map(item=>({number:item.number,revision:item.revision})),title:chapter.title,body:chapter.body},'human'));
  return {kind:input.kind,source:input.source,inputSha256:createHash('sha256').update(bytes).digest('hex'),scope:input.scope,work,chapters,export:store.exportWork(work.id),fiveTables:snapshot(store)};
}
if(process.argv[1]&&resolve(process.argv[1])===resolve(import.meta.filename)){
  const {values}=parseArgs({options:{name:{type:'string'}}}),id=values.name??randomUUID();
  if(!/^[a-zA-Z0-9-]+$/.test(id))throw new Error('练习名称只用字母、数字和连字符。');
  const directory=resolve('runs',`prepare-${id}`),database=resolve('data',`practice-${id}.sqlite`);
  if(existsSync(directory)||existsSync(database))throw new Error('同名练习已存在，请换新名称；不会覆盖原件。');
  mkdirSync(directory,{recursive:true});const store=new Store(database);let result;
  try{result=seed(store);}finally{store.close();}
  const report={id,database,workId:result.work.id,preparedAt:new Date().toISOString(),modelRequests:0,...result};
  writeFileSync(resolve(directory,'report.json'),JSON.stringify(report,null,2)+'\n');
  writeFileSync('practice.json',JSON.stringify({id,database,workId:result.work.id,preparedFrom:directory},null,2)+'\n');
  console.log(JSON.stringify({id,database,workId:result.work.id,directory,counts:Object.fromEntries(tables.map(name=>[name,result.fiveTables[name].length])),modelRequests:0}));
}

import {DatabaseSync} from 'node:sqlite';
import {mkdirSync} from 'node:fs';
import {dirname} from 'node:path';
import assert from 'node:assert/strict';
import {LabError,type WorkInput,type DraftInput,type ApprovedExcerpt} from './schemas.js';

export type Work=WorkInput & {revision:number};
export type Chapter={workId:string;number:number;revision:number;title:string;body:string;status:'draft'|'adopted';workRevision:number;origin:'human'|'agent';taskId:string|null;threadId:string|null;updatedAt:string;previousRevisions?:{number:number;revision:number}[];reviewNote?:string|null};
export type Task={id:string;workId:string;chapterNumber:number;threadId:string|null;state:'created'|'running'|'completed'|'failed'|'cancelled'|'interrupted';codeVersion:string;createdAt:string;updatedAt:string;error:string|null;usage:unknown};

export class Store {
  readonly db:DatabaseSync;
  constructor(path:string){
    if(path!==':memory:')mkdirSync(dirname(path),{recursive:true});
    this.db=new DatabaseSync(path,{timeout:2000});
    this.db.exec(`
      PRAGMA journal_mode=WAL;
      CREATE TABLE IF NOT EXISTS works(id TEXT PRIMARY KEY, revision INTEGER NOT NULL, content TEXT NOT NULL) STRICT;
      CREATE TABLE IF NOT EXISTS work_versions(work_id TEXT NOT NULL REFERENCES works(id), revision INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(work_id,revision)) STRICT;
      CREATE TABLE IF NOT EXISTS chapters(work_id TEXT NOT NULL REFERENCES works(id), number INTEGER NOT NULL, revision INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(work_id,number)) STRICT;
      CREATE TABLE IF NOT EXISTS chapter_versions(work_id TEXT NOT NULL, number INTEGER NOT NULL, revision INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(work_id,number,revision), FOREIGN KEY(work_id,number) REFERENCES chapters(work_id,number)) STRICT;
      CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, content TEXT NOT NULL) STRICT;
    `);
  }
  close(){this.db.close();}
  private transaction<T>(action:()=>T):T{
    // 读取基线与写入处于同一事务，两个入口不能越过修订检查。
    this.db.exec('BEGIN IMMEDIATE');
    try{const result=action();this.db.exec('COMMIT');return result;}
    catch(error){this.db.exec('ROLLBACK');throw error;}
  }
  init(input:WorkInput):Work{
    if(this.db.prepare('SELECT id FROM works WHERE id=?').get(input.id))throw new LabError('WORK_EXISTS','作品已存在，初始化不会覆盖它。');
    if(input.outline.some((item,index)=>item.number!==index+1))throw new LabError('OUTLINE_ORDER','大纲章节必须从 1 开始连续排列。');
    return this.transaction(()=>{
      const content=JSON.stringify(input);
      this.db.prepare('INSERT INTO works VALUES(?,?,?)').run(input.id,1,content);
      this.db.prepare('INSERT INTO work_versions VALUES(?,?,?)').run(input.id,1,content);
      return {...input,revision:1};
    });
  }
  getWork(id:string):Work{
    const row=this.db.prepare('SELECT revision,content FROM works WHERE id=?').get(id);
    if(!row)throw new LabError('WORK_NOT_FOUND',`没有作品 ${id}，先初始化。`);
    return {...JSON.parse(row.content as string),revision:Number(row.revision)};
  }
  listWorks():Work[]{
    return this.db.prepare('SELECT revision,content FROM works ORDER BY id').all().map(row=>({...JSON.parse(row.content as string),revision:Number(row.revision)}));
  }
  getChapter(workId:string,number:number):Chapter|null{
    this.getWork(workId);
    return this.findChapter(workId,number);
  }
  private findChapter(workId:string,number:number):Chapter|null{
    const row=this.db.prepare('SELECT content FROM chapters WHERE work_id=? AND number=?').get(workId,number);
    return row?JSON.parse(row.content as string):null;
  }
  updateWork(input:WorkInput,expectedRevision:number):Work{
    return this.transaction(()=>{
      const current=this.getWork(input.id);
      if(current.revision!==expectedRevision)throw new LabError('STALE_WORK',`要求已是 r${current.revision}，请重读后再修改。`);
      if(input.outline.some((item,index)=>item.number!==index+1))throw new LabError('OUTLINE_ORDER','大纲章节必须从 1 开始连续排列。');
      const saved=this.db.prepare('SELECT number FROM chapters WHERE work_id=?').all(current.id);
      if(saved.some(row=>!input.outline.some(item=>item.number===row.number)))throw new LabError('OUTLINE_HAS_SAVED_CHAPTER','大纲不能静默移除已保存的章节。');
      const revision=current.revision+1;
      // 改写前保存当前原始资料，修订引用有实际文本可回查。
      this.db.prepare('INSERT INTO work_versions SELECT id,revision,content FROM works WHERE id=? ON CONFLICT(work_id,revision) DO NOTHING').run(current.id);
      const content=JSON.stringify(input);
      this.db.prepare('UPDATE works SET revision=?,content=? WHERE id=?').run(revision,content,current.id);
      this.db.prepare('INSERT INTO work_versions VALUES(?,?,?)').run(current.id,revision,content);
      return {...input,revision};
    });
  }
  getWorkVersion(id:string,revision:number):Work{
    this.getWork(id);
    const row=this.db.prepare('SELECT content FROM work_versions WHERE work_id=? AND revision=?').get(id,revision);
    if(!row)throw new LabError('WORK_VERSION_NOT_FOUND','没有保存这个资料修订。');
    return {...JSON.parse(row.content as string),revision};
  }
  private persistChapter(chapter:Chapter):Chapter{
    const content=JSON.stringify(chapter);
    this.db.prepare('INSERT INTO chapters VALUES(?,?,?,?) ON CONFLICT(work_id,number) DO UPDATE SET revision=excluded.revision,content=excluded.content').run(chapter.workId,chapter.number,chapter.revision,content);
    this.db.prepare('INSERT INTO chapter_versions VALUES(?,?,?,?)').run(chapter.workId,chapter.number,chapter.revision,content);
    return chapter;
  }
  listChapters(workId:string):Omit<Chapter,'body'>[]{
    this.getWork(workId);
    const rows=this.db.prepare('SELECT content FROM chapters WHERE work_id=? ORDER BY number').all(workId);
    return rows.map(row=>{const {body,...chapter}=JSON.parse(row.content as string) as Chapter;return chapter;});
  }
  saveDraft(input:DraftInput,origin:'human'|'agent',taskId:string|null=null):Chapter{
    return this.transaction(()=>{
      const work=this.getWork(input.workId);
      if(work.revision!==input.expectedWorkRevision)throw new LabError('STALE_WORK',`要求已是 r${work.revision}，请重读后再保存。`);
      if(!work.outline.some(item=>item.number===input.chapterNumber))throw new LabError('CHAPTER_OUT_OF_SCOPE','本章不在当前已确认的大纲中。');
      const current=this.findChapter(work.id,input.chapterNumber);
      if((current?.revision??0)!==input.expectedChapterRevision)throw new LabError('STALE_CHAPTER',`正文已是 r${current?.revision??0}，请重读后合并。`);
      const bases=[...input.expectedPreviousRevisions].sort((a,b)=>a.number-b.number);
      if(bases.length!==input.chapterNumber-1||bases.some((item,index)=>item.number!==index+1))throw new LabError('PREVIOUS_BASES_REQUIRED','需要逐项提供前面全部章节的当前修订。');
      for(const base of bases){
        const previous=this.findChapter(work.id,base.number);
        if(!previous)throw new LabError('PREVIOUS_CHAPTER_MISSING',`第 ${base.number} 章尚未保存。`);
        if(previous.revision!==base.revision)throw new LabError('STALE_PREVIOUS',`第 ${base.number} 章已经是 r${previous.revision}，请读取当前正文后再续写。`);
      }
      const task=taskId?this.getTask(taskId):null;
      if(task&&(task.workId!==work.id||task.chapterNumber!==input.chapterNumber))throw new LabError('TASK_MISMATCH','任务与本章不一致。');
      const chapter:Chapter={workId:work.id,number:input.chapterNumber,revision:(current?.revision??0)+1,title:input.title,body:input.body,status:'draft',workRevision:work.revision,origin,taskId,threadId:task?.threadId??null,updatedAt:new Date().toISOString(),previousRevisions:bases,reviewNote:null};
      return this.persistChapter(chapter);
    });
  }
  reviseExcerpt(scope:ApprovedExcerpt,replacement:string,origin:'human'|'agent',taskId:string|null=null):Chapter{
    const current=this.getChapter(scope.workId,scope.chapterNumber);
    if(!current)throw new LabError('CHAPTER_NOT_FOUND','还没有该章正文，不能局部修改。');
    if(current.revision!==scope.expectedChapterRevision)throw new LabError('STALE_CHAPTER',`正文已是 r${current.revision}，请重读后重新选定范围。`);
    if(scope.end>current.body.length||current.body.slice(scope.start,scope.end)!==scope.originalText)throw new LabError('EXCERPT_MISMATCH','当前正文与人工选区不一致，请重读后重新选定范围。');
    // UTF-16 选区外沿用当前原文，事务内的修订检查仍由同一保存函数承担。
    return this.saveDraft({...scope,title:current.title,body:current.body.slice(0,scope.start)+replacement+current.body.slice(scope.end)},origin,taskId);
  }
  adopt(workId:string,number:number,expectedRevision:number,note:string):Chapter{
    return this.transaction(()=>{
      const work=this.getWork(workId);
      const current=this.findChapter(work.id,number);
      if(!current)throw new LabError('CHAPTER_NOT_FOUND','还没有该章正文。');
      if(current.revision!==expectedRevision)throw new LabError('STALE_CHAPTER',`正文已是 r${current.revision}，不能采用旧版本。`);
      return this.persistChapter({...current,revision:current.revision+1,status:'adopted',origin:'human',reviewNote:note,updatedAt:new Date().toISOString()});
    });
  }
  exportWork(id:string){
    const work=this.getWork(id);
    const rows=this.db.prepare('SELECT content FROM chapters WHERE work_id=? ORDER BY number').all(id);
    const chapters=rows.map(row=>JSON.parse(row.content as string) as Chapter);
    const details=chapters.map(chapter=>{
      if(chapter.number>1)assert(chapter.previousRevisions,'连续章节缺少保存时的前文基线');
      const previousChanged=(chapter.previousRevisions??[]).some(base=>this.findChapter(id,base.number)?.revision!==base.revision);
      return {number:chapter.number,revision:chapter.revision,status:chapter.status,workRevision:chapter.workRevision,previousRevisions:chapter.previousRevisions??[],reviewNote:chapter.reviewNote??null,basisCurrent:chapter.workRevision===work.revision&&!previousChanged};
    });
    const text=`# ${work.title}\n\n用途：${work.purpose}\n\n`+chapters.map((chapter,index)=>`## 第 ${chapter.number} 章 ${chapter.title}\n\n状态：${chapter.status}，正文 r${chapter.revision}；${details[index].basisCurrent?'资料基线一致，品质仍需人判断':'资料有变动，需重新核对'}。\n\n${chapter.reviewNote?`采用说明：${chapter.reviewNote}\n\n`:''}${chapter.body}\n`).join('\n');
    return {workId:id,workRevision:work.revision,expectedChapters:work.outline.length,savedChapters:chapters.length,allOutlineChaptersSaved:chapters.length===work.outline.length&&chapters.every((chapter,index)=>chapter.number===index+1),chapters:details,text};
  }
  createTask(input:Pick<Task,'id'|'workId'|'chapterNumber'|'codeVersion'>):Task{
    const work=this.getWork(input.workId);
    if(!work.outline.some(item=>item.number===input.chapterNumber))throw new LabError('CHAPTER_OUT_OF_SCOPE','任务章节不在大纲中。');
    const now=new Date().toISOString();
    const task:Task={...input,threadId:null,state:'created',createdAt:now,updatedAt:now,error:null,usage:null};
    this.db.prepare('INSERT INTO tasks VALUES(?,?)').run(task.id,JSON.stringify(task));return task;
  }
  getTask(id:string):Task{
    const row=this.db.prepare('SELECT content FROM tasks WHERE id=?').get(id);
    if(!row)throw new LabError('TASK_NOT_FOUND','任务记录不存在。');return JSON.parse(row.content as string);
  }
  updateTask(id:string,change:Partial<Pick<Task,'threadId'|'state'|'error'|'usage'>>):Task{
    const task={...this.getTask(id),...change,updatedAt:new Date().toISOString()};
    this.db.prepare('UPDATE tasks SET content=? WHERE id=?').run(JSON.stringify(task),id);return task;
  }
}

const $=id=>document.getElementById(id);
const parameters=new URLSearchParams(location.search);
let workId=parameters.get('work'),snapshot=null,selected=Number(parameters.get('chapter')??1),busy=false,uncertain=false;
const edits=new Map();
let pendingRemote=null;
function message(text,kind='normal',read=false,code=''){$('message').textContent=text;$('message').dataset.kind=kind;$('read-current').hidden=!read;$('error-detail').hidden=!code;$('error-code').textContent=code;$('error-detail').open=false;}
function failure(error){const text=error.code==='STALE_CHAPTER'?'这一章已保存了新稿。':error.code==='STALE_WORK'?'作品资料已有变化。':error.code?.startsWith('STALE_')?'前文章节已有变化。':error.code==='NETWORK_UNCONFIRMED'?'连接中断，尚未确认保存结果。':error.message;message(text+' 本地修改仍保留，请读取当前稿后对照。','error',true,error.code);}
async function request(path,options){let response;try{response=await fetch(path,options);}catch{const error=new Error('无法连接服务。本次请求未确认，本地修改仍保留；恢复连接后先读取当前稿。');error.code='NETWORK_UNCONFIRMED';throw error;}const value=await response.json();if(!response.ok){const error=new Error(value.error.message);error.code=value.error.code;throw error;}return value;}
function edit(){return edits.get(selected);}
function isDirty(value=edit()){return !!value&&(value.title!==value.base.title||value.body!==value.base.body);}
function sync(){const current=edit();if(!current)return;current.title=$('draft-title').value;current.body=$('draft-body').value;$('edit-state').textContent=isDirty()?'有未保存修改':'';$('save').disabled=busy||uncertain||!isDirty();}
function setBusy(value){busy=value;$('draft-title').disabled=value||!snapshot;$('draft-body').disabled=value||!snapshot;$('use-current').disabled=value;$('reload').disabled=value;$('read-current').disabled=value;$('save').disabled=value||uncertain||!isDirty();for(const button of $('chapters').querySelectorAll('button'))button.disabled=value;}
function context(){const container=$('work-context');container.replaceChildren();for(const [title,items] of [['用途',[snapshot.work.purpose]],['要求',snapshot.work.requirements],['已确认设定',snapshot.work.facts],['大纲',snapshot.work.outline.map(o=>'第 '+o.number+' 章 '+o.titleHint+'：'+o.goal)]]){const heading=document.createElement('h3');heading.textContent=title;const list=document.createElement('ul');for(const text of items){const item=document.createElement('li');item.textContent=text;list.append(item);}container.append(heading,list);}}
function navigation(){const nav=$('chapters');nav.replaceChildren();for(const chapter of snapshot.chapters){const button=document.createElement('button');button.type='button';button.className='chapter';button.dataset.number=String(chapter.number);button.setAttribute('aria-current',chapter.number===selected?'page':'false');const number=document.createElement('span');number.className='chapter-number';number.textContent=String(chapter.number).padStart(2,'0');const text=document.createElement('span');const title=document.createElement('strong');title.textContent=chapter.title;const state=document.createElement('small');state.textContent='r'+chapter.revision+' · '+(chapter.status==='draft'?'草稿':'已采用')+(chapter.basisCurrent?'':' · 依据有变动');text.append(title,state);button.append(number,text);button.addEventListener('click',()=>{sync();selected=chapter.number;pendingRemote=null;$('comparison').hidden=true;render();message('');});nav.append(button);}}
function render(){if(!snapshot)return;const chapter=snapshot.chapters.find(c=>c.number===selected);if(!chapter){message('该章尚未保存。','error');return;}if(!edits.has(selected))edits.set(selected,{base:structuredClone(chapter),workRevision:snapshot.work.revision,previous:snapshot.chapters.filter(c=>c.number<selected).map(c=>({number:c.number,revision:c.revision})),title:chapter.title,body:chapter.body});const current=edit();$('work-title').textContent=snapshot.work.title;$('chapter-label').textContent='第 '+selected+' 章 · 当前草稿';$('revision').textContent='读取 r'+current.base.revision+' · '+(current.base.status==='draft'?'草稿':'已采用')+' · '+(current.base.basisCurrent?'依据当前':'依据有变动');$('draft-title').disabled=busy;$('draft-body').disabled=busy;$('draft-title').value=current.title;$('draft-body').value=current.body;navigation();context();sync();}
async function readCurrent(){setBusy(true);try{const incoming=await request('/api/work?work='+encodeURIComponent(workId));snapshot=incoming;const chapter=incoming.chapters.find(c=>c.number===selected);if(isDirty()){pendingRemote=chapter;$('remote-heading').textContent='当前已保存稿 · r'+chapter.revision;$('remote-body').value=chapter.body;$('comparison').hidden=false;message('当前已保存稿已读回。本地修改仍在上方，请先对照。','notice');}else{edits.delete(selected);$('comparison').hidden=true;message('');}uncertain=false;render();}catch(error){failure(error);}finally{setBusy(false);}}
$('draft-title').addEventListener('input',sync);$('draft-body').addEventListener('input',sync);
$('draft-form').addEventListener('submit',async event=>{event.preventDefault();sync();if(!isDirty()||busy||uncertain)return;const current=edit();setBusy(true);message('正在保存草稿。');const input={workId,chapterNumber:selected,expectedWorkRevision:current.workRevision,expectedChapterRevision:current.base.revision,expectedPreviousRevisions:current.previous,title:current.title,body:current.body};try{const saved=await request('/api/draft',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)});const incoming=await request('/api/work?work='+encodeURIComponent(workId));snapshot=incoming;edits.delete(selected);pendingRemote=null;$('comparison').hidden=true;render();message('已保存 r'+saved.revision+'。');}catch(error){uncertain=error.code==='NETWORK_UNCONFIRMED'||error.code==='INTERNAL_ERROR';failure(error);}finally{setBusy(false);}});
$('reload').addEventListener('click',readCurrent);$('read-current').addEventListener('click',readCurrent);
$('use-current').addEventListener('click',()=>{if(!pendingRemote)return;edits.delete(selected);pendingRemote=null;$('comparison').hidden=true;uncertain=false;render();message('');});
window.addEventListener('beforeunload',event=>{if([...edits.values()].some(isDirty)){event.preventDefault();event.returnValue='';}});
try{if(!workId)workId=(await request('/api/config')).workId;snapshot=await request('/api/work?work='+encodeURIComponent(workId));render();message('');}catch(error){failure(error);$('draft-title').disabled=true;$('draft-body').disabled=true;}

