26:   private transaction<T>(action:()=>T):T{
27:     // 读取基线与写入处于同一事务，两个入口不能越过修订检查。
28:     this.db.exec('BEGIN IMMEDIATE');
29:     try{const result=action();this.db.exec('COMMIT');return result;}
30:     catch(error){this.db.exec('ROLLBACK');throw error;}
