62:       if(input.outline.some((item,index)=>item.number!==index+1))throw new LabError('OUTLINE_ORDER','大纲章节必须从 1 开始连续排列。');
63:       const saved=this.db.prepare('SELECT number FROM chapters WHERE work_id=?').all(current.id);
