65:       const revision=current.revision+1;
66:       // 改写前保存当前原始资料，修订引用有实际文本可回查。
67:       this.db.prepare('INSERT INTO work_versions SELECT id,revision,content FROM works WHERE id=? ON CONFLICT(work_id,revision) DO NOTHING').run(current.id);
68:       const content=JSON.stringify(input);
69:       this.db.prepare('UPDATE works SET revision=?,content=? WHERE id=?').run(revision,content,current.id);
