91:   saveDraft(input:DraftInput,origin:'human'|'agent',taskId:string|null=null):Chapter{
92:     return this.transaction(()=>{
93:       const work=this.getWork(input.workId);
94:       if(work.revision!==input.expectedWorkRevision)throw new LabError('STALE_WORK',`要求已是 r${work.revision}，请重读后再保存。`);
95:       if(!work.outline.some(item=>item.number===input.chapterNumber))throw new LabError('CHAPTER_OUT_OF_SCOPE','本章不在当前已确认的大纲中。');
96:       const current=this.findChapter(work.id,input.chapterNumber);
97:       if((current?.revision??0)!==input.expectedChapterRevision)throw new LabError('STALE_CHAPTER',`正文已是 r${current?.revision??0}，请重读后合并。`);
98:       const bases=[...input.expectedPreviousRevisions].sort((a,b)=>a.number-b.number);
99:       if(bases.length!==input.chapterNumber-1||bases.some((item,index)=>item.number!==index+1))throw new LabError('PREVIOUS_BASES_REQUIRED','需要逐项提供前面全部章节的当前修订。');
100:       for(const base of bases){
101:         const previous=this.findChapter(work.id,base.number);
102:         if(!previous)throw new LabError('PREVIOUS_CHAPTER_MISSING',`第 ${base.number} 章尚未保存。`);
103:         if(previous.revision!==base.revision)throw new LabError('STALE_PREVIOUS',`第 ${base.number} 章已经是 r${previous.revision}，请读取当前正文后再续写。`);
104:       }
105:       const task=taskId?this.getTask(taskId):null;
106:       if(task&&(task.workId!==work.id||task.chapterNumber!==input.chapterNumber))throw new LabError('TASK_MISMATCH','任务与本章不一致。');
107:       const chapter:Chapter={workId:work.id,number:input.chapterNumber,revision:(current?.revision??0)+1,title:input.title,body:input.body,status:'draft',workRevision:work.revision,origin,taskId,threadId:task?.threadId??null,updatedAt:new Date().toISOString(),previousRevisions:bases,reviewNote:null};
108:       return this.persistChapter(chapter);
109:     });
110:   }
